n" class="form-select"><option value="">انتخاب علت...</option>@foreach($returnReasons as $key=>$label)<option value="{{ $key }}" @selected(old('return_reason',$document->return_reason??'')===$key)>{{ $label }}</option>@endforeach</select></div><div class="col-12 internal-only"><div class="invoice-summary" id="invoiceSummaryBox"><strong>خلاصه فاکتور:</strong> <span id="invoiceSummaryText">{{ $invoiceSummary ? ('شماره '.$invoiceSummary['uuid'].' | مبلغ '.number_format($invoiceSummary['total']).' ریال | تعداد اقلام '.$invoiceSummary['items_count']) : 'هنوز فاکتوری انتخاب نشده است.' }}</span></div></div></div></div></div>
